import itertools

# Ciphertext as bytes
encrypted_hex = ""
ciphertext = bytes.fromhex(encrypted_hex)

# Some parameters
possible_key_lengths = list(range(11, 21))
flag_start = b'flag{' # Known flag prefix

printable = set(range(0x20, 0x7f))

results = []

# Function to check if string is mostly printable
def mostly_printable(b):
    return sum(x in printable for x in b) > int(0.9 * len(b))

def try_key(ciphertext, key):
    out = bytearray()
    for i in range(len(ciphertext)):
        out.append(ciphertext[i] ^ key[i % len(key)])
    return bytes(out)

# Try all key alignments for eivgy (len 5) and its cyclic rotations
candidate_key = b'eivgy'
for shift in range(len(candidate_key)):
    k = candidate_key[shift:] + candidate_key[:shift]
    out = try_key(ciphertext, k)
    idx = out.find(flag_start)
    if idx != -1:
        results.append(("align-eivgy", shift, k, idx, out[idx:idx+40]))

# Try partial period (shorter keys) of eivgy, e.g. 3 or 4 letters
for plen in range(2, 5):
    for start in range(len(candidate_key)-plen+1):
        k = candidate_key[start:start+plen]
        out = try_key(ciphertext, k)
        idx = out.find(flag_start)
        if idx != -1:
            results.append(("partial-eivgy", k, idx, out[idx:idx+40]))

# Try all key lengths from 11 to 20
for keylen in possible_key_lengths:
    for offset in range(keylen):
        # Try to deduce key from all possible positions that could reveal flag{
        for pos in range(len(ciphertext)-len(flag_start)):
            # Derive candidate key fragment that would produce flag{
            k = [0]*keylen
            for i in range(len(flag_start)):
                k[(pos+i+offset) % keylen] = ciphertext[pos+i] ^ flag_start[i]
            kbytes = bytearray(k)
            # Try to fill entire key with this fragment (repeated if fragment smaller than keylen)
            out = try_key(ciphertext, kbytes)
            idx = out.find(flag_start)
            if idx != -1 and mostly_printable(out[idx:idx+40]):
                # found candidate
                results.append(("brute-keylen", keylen, offset, pos, kbytes, idx, out[idx:idx+40]))

# Output the results
for r in results:
    print(r)
    # Print only best match as flag
    if b'flag{' in r[-1]:
        print(f"Plausible plaintext with flag: {r[-1]}")

