import string
from collections import Counter

def xor_decrypt(data, key):
    klen = len(key)
    return bytes([b ^ key[i % klen] for i, b in enumerate(data)])

with open('/home/ctfplayer/ctf_files/encrypted', 'r') as f:
    hexdata = f.read().strip()
data = bytes.fromhex(hexdata)

flag_hits = Counter()
context_samples = {}

def is_printable_ascii(s):
    return all(32 <= ord(c) < 127 for c in s)

# Try key lengths from 2 to 16
for klen in range(2, 17):
    for key_guess in range(256**min(3,klen)):
        guessbytes = list(key_guess.to_bytes(min(3,klen), 'big'))
        key = guessbytes + [0]*(klen-len(guessbytes))
        key = bytes(key)
        pt = xor_decrypt(data, key)
        try:
            text = pt.decode('latin1', errors='replace')
        except:
            continue
        idx = text.find('flag{')
        while idx >= 0:
            ctx_start = max(0, idx-8)
            ctx_end = min(len(text), idx+40)
            snippet = text[ctx_start:ctx_end]
            flag_end = text.find('}', idx)
            if flag_end != -1:
                candidate = text[idx:flag_end+1]
                flag_content = candidate[5:-1]
                if is_printable_ascii(flag_content):
                    flag_hits[candidate] += 1
                    context_samples[candidate] = snippet
            idx = text.find('flag{', idx+1)

print('==== TOP TEN hits ===')
for flag, count in flag_hits.most_common(10):
    snippet = context_samples[flag]
    print(f'[{count}x] ...{snippet}...')
    print('    -->', flag)

