    l = len(key)
    return bytes([b ^ key[i % l] for i, b in enumerate(data)])

def is_printable(s):
    return all(32 <= ord(c) < 127 for c in s)

with open('/home/ctfplayer/ctf_files/encrypted', 'r') as f:
    ct = bytes.fromhex(f.read().strip())

flag_hits = Counter()
ctx = {}

# for likely XOR length 4 to 12 (common CTF range)
for klen in range(4,13):
    for align in range(klen):
        positions = list(range(align, len(ct), klen))
        # Guess likely key bytes at "flag{" locations
        for pos in positions:
            if pos+5 > len(ct):
                break
            # Test for key that would make ct[pos:pos+5]==flag{
            target = b'flag{'
            key_guess = [(ct[pos+i] ^ target[i]) for i in range(min(5,len(ct)-pos))]
            # Build full key guess by repeating guessed bytes
            full_key = bytes((key_guess * (klen//len(key_guess)+1))[:klen])
            pt = xor(ct, full_key)
            try:
                text = pt.decode('latin1', errors='replace')
            except:
                continue
            idx = text.find('flag{')
            while idx != -1:
                endidx = text.find('}', idx)
                if endidx != -1:
                    candidate = text[idx:endidx+1]
                    flag_content = candidate[5:-1]
                    if is_printable(flag_content):
                        flag_hits[candidate] += 1
                        ctx[candidate] = text[max(0,idx-8):min(len(text),endidx+12)]
                idx = text.find('flag{', idx+1)

for flag, count in flag_hits.most_common(10):
    snippet = ctx[flag]
    print(f'[{count}x] ...{snippet}...')
    print('    -->', flag)

