import string
from itertools import product
import re

# Read hex-encoded ciphertext
encrypted_path = '/home/ctfplayer/ctf_files/encrypted'
with open(encrypted_path, 'r') as f:
    hex_string = f.read().strip()

data = bytes.fromhex(hex_string)

candidates = set()
FLAG_FMT = re.compile(rb'flag\{([^}]*)\}')
PRINTABLE = set(bytes(string.printable, 'ascii'))

# Try key length 2..16
min_key_len = 2
max_key_len = 16
crib = b'flag{'  # known flag start
crib_len = len(crib)

for key_len in range(min_key_len, max_key_len+1):
    # For each possible position for the crib, calculate key bytes that would yield 'flag{'
    for offset in range(len(data) - crib_len + 1):
        partial_key = [None] * key_len
        key_found = True
        for i in range(crib_len):
            key_pos = (offset + i) % key_len
            val = data[offset + i] ^ crib[i]
            if partial_key[key_pos] is None:
                partial_key[key_pos] = val
            elif partial_key[key_pos] != val:
                key_found = False
                break
        if not key_found:
            continue
        # At this point, partial_key has bytes or None
        # Fill None with all possibilities (try all printable)
        def generate_keys(partial_key):
            slots = []
            for idx, b in enumerate(partial_key):
                if b is None:
                    slots.append(idx)
            printable_bytes = [ord(c) for c in string.printable]
            for combo in product(printable_bytes, repeat=len(slots)):
                new_key = list(partial_key)
                for i, slot in enumerate(slots):
                    new_key[slot] = combo[i]
                yield bytes(new_key)

        for key in generate_keys(partial_key):
            plain = bytearray()
            for i in range(len(data)):
                plain.append(data[i] ^ key[i % key_len])
            # Look for flag{...} payloads
            for m in FLAG_FMT.finditer(plain):
                start = m.start()
                end = m.end()
                flag_bytes = plain[start:end]
                # Clean up flag if needed (non-printable inside braces)
                inner = m.group(1)
                if all(b in PRINTABLE for b in inner):
                    flag = flag_bytes
                else:
                    # hex-encode non-printables inside the braces
                    inner2 = b''
                    for b in inner:
                        if b in PRINTABLE and b != 0x7f:
                            inner2 += bytes([b])
                        else:
                            inner2 += (b'\\x%02x' % b)
                    flag = b'flag{' + inner2 + b'}'
                # Only keep plausible candidates
                if 20 <= len(flag) <= 80 and b'flag{' in flag and b'}' in flag:
                    candidates.add(flag.decode('ascii',errors='replace'))
# Print unique candidates
for flag in sorted(candidates):
    print(flag)

