import itertools
import re
from collections import Counter, defaultdict

# Load ciphertext from hexdump output (provided)
hexdata = ""

def hexstr_to_bytes(s):
    return bytes.fromhex(s)

cipher = hexstr_to_bytes(hexdata)

# Setup
MIN_KEYLEN = 2
MAX_KEYLEN = 16
FLAGHEAD = b'flag{'
FLAGHEADLEN = len(FLAGHEAD)

# Will store all found candidates (offset, keylen, key, startidx, endidx, raw_bytes)
candidates = []
flag_subs_counter = Counter()
flag_subs_bylen = defaultdict(list)

# Helper: get all substrings starting with flag{ and ending at next }
def extract_flaglike(data):
    found = []
    i = 0
    while i < len(data):
        s = data.find(b'flag{', i)
        if s == -1:
            break
        e = data.find(b'}', s+5)
        if e != -1:
            found.append(data[s:e+1])
            i = s + 1
        else:
            break
    return found

for keylen in range(MIN_KEYLEN, MAX_KEYLEN+1):
    for offset in range(keylen):
        # rotate data so start at each possible offset
        part = cipher[offset:]
        nblocks = (len(part) + keylen - 1) // keylen
        for kidx in range(len(part) - FLAGHEADLEN + 1):
            # Try to crib-drag the flag head
            guess_key = []
            for j in range(FLAGHEADLEN):
                cbyte = part[kidx+j]
                guess_key.append(cbyte ^ FLAGHEAD[j])
            # Use this guess as keystream starting at aligned offset
            fullkey = bytearray(keylen)
            for j in range(FLAGHEADLEN):
                fullkey[(kidx+j)%keylen] = guess_key[j]
            # Fill rest (unknown) with zero for now
            plain = bytearray()
            for idx, cb in enumerate(part):
                k = fullkey[idx%keylen]
                plain.append(cb ^ k)
            # Extract all flag-like substrings
            found = extract_flaglike(plain)
            for candidate in found:
                candidates.append((keylen, offset, kidx, fullkey.copy(), candidate))
                flag_subs_counter[candidate] += 1
                flag_subs_bylen[len(candidate)].append(candidate)

# Top 10 longest
uniq_candidates = {c[-1] for c in candidates}
longest = sorted(uniq_candidates, key=lambda x: -len(x))[:10]
mostfreq = [item[0] for item in flag_subs_counter.most_common(10)]

# Output all (hex if not printable, raw if printable)
def is_printable(bs):
    try:
        s = bs.decode('ascii')
    except Exception:
        return False
    return all(32 <= b < 127 for b in bs)

print("Top 10 longest substrings:")
for cand in longest:
    if is_printable(cand):
        print(cand.decode(), "[PRINTABLE]")
    else:
        print(cand.hex(), "[HEX]")
print("\nTop 10 most frequent substrings:")
for cand in mostfreq:
    if is_printable(cand):
        print(cand.decode(), "[PRINTABLE]")
    else:
        print(cand.hex(), "[HEX]")
# Print any fully printable as text at end for clarity
for cand in uniq_candidates:
    if is_printable(cand):
        print("PRINTABLE FLAGLIKELY:", cand.decode())

